const {chromium}=require('playwright'),http=require('http'),fs=require('fs'),path=require('path'),assert=require('assert/strict');
const assets=path.resolve(__dirname,'../../internal/domaininit/assets'),out=process.env.SAMBAADM_MEMBER_SCREENSHOTS||'/tmp/sambaadm-member-ui';fs.mkdirSync(out,{recursive:true});
const server=http.createServer((req,res)=>{const file=path.join(assets,req.url==='/'?'index.html':req.url.replace('/assets/',''));if(!file.startsWith(assets)||!fs.existsSync(file)){res.writeHead(404).end();return;}res.setHeader('Content-Type',file.endsWith('.js')?'application/javascript':file.endsWith('.css')?'text/css':'text/html');res.end(fs.readFileSync(file));});
(async()=>{await new Promise(r=>server.listen(0,'127.0.0.1',r));const browser=await chromium.launch();try{
 for(const profile of ['winbind','sssd']){
 const page=await browser.newPage({viewport:{width:1280,height:1000}}),errors=[];let unlocked=false,starts=0;
 page.on('pageerror',e=>errors.push(e.message));
 await page.route('**/api**',async route=>{const req=route.request(),url=new URL(req.url());let value={csrf:'test-csrf'},code=200;
 if(url.pathname.endsWith('/unlock'))unlocked=true;else if(!unlocked){code=401;value={error:'Введите код'};}
 else if(url.pathname.endsWith('/plan')){const input=req.postDataJSON();assert.equal(input.mode,'member');assert.equal(input.identityProvider,profile);assert.equal(input.site,'');assert.equal(input.level,'');assert(!input.password);assert(!input.serviceUser);value={revision:'a'.repeat(64),checks:['Сервер готов','Профиль: '+profile],steps:['Присоединить файловый сервер','Проверить UID/GID и ACL']};}
 else if(url.pathname.endsWith('/start')){starts++;const input=req.postDataJSON();assert.equal(input.password,'PrivateSecretA1!');assert.equal(input.username,'Administrator@corp.example');assert.equal(input.identityProvider,profile);value={id:'a'.repeat(32),mode:'member',realm:'corp.example',state:'queued'};}
 else if(url.pathname.endsWith('/status'))value={id:'a'.repeat(32),mode:'member',state:'completed',panelURL:'https://sambaadm.corp.example',log:['Доверие, UID/GID, ACL и xattr проверены']};
 await route.fulfill({status:code,json:value});});
 await page.goto('http://127.0.0.1:'+server.address().port);await page.getByLabel('Код доступа').fill('training-code');await page.getByRole('button',{name:'Открыть мастер'}).click();
 await page.getByLabel('Сценарий установки').selectOption('member');await page.getByLabel('Доменные пользователи и группы').selectOption(profile);await page.getByLabel('DNS-имя домена / леса').fill('corp.example');await page.getByLabel('Короткое имя домена').fill('CORP');await page.getByLabel('Имя файлового сервера',{exact:true}).fill('fs1');await page.getByLabel('Постоянный IPv4 сервера').fill('192.0.2.20');await page.getByLabel('Контроллер домена',{exact:true}).fill('dc1.corp.example');await page.getByLabel('Доменный DNS').fill('192.0.2.10');await page.getByLabel('HTTPS-имя существующей панели').fill('sambaadm.corp.example');
 assert.equal(await page.getByLabel('Уровень леса и домена').count(),0);assert.equal(await page.getByLabel('Новая служебная запись панели').count(),0);await page.locator('.di-shell').screenshot({path:path.join(out,profile+'-parameters.png')});
 await page.setViewportSize({width:390,height:844});assert(!await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth));await page.setViewportSize({width:1280,height:1000});
 await page.getByRole('button',{name:'Далее: проверить сервер'}).click();await page.getByRole('button',{name:'Проверить сервер и пакеты'}).click();await page.getByText('Сервер готов',{exact:true}).waitFor();await page.getByRole('button',{name:'Далее',exact:true}).click();
 await page.getByLabel('Учётная запись для присоединения').fill('Administrator@corp.example');await page.getByLabel('Пароль доменной учётной записи').fill('PrivateSecretA1!');await page.getByLabel('Повторите пароль').fill('PrivateSecretA1!');await page.getByRole('checkbox').check();await page.getByRole('button',{name:'Установить файловый сервер',exact:true}).click();
 const link=page.getByRole('link',{name:'Подключить файловый сервер к панели'});await link.waitFor();assert.equal(await link.getAttribute('href'),'https://sambaadm.corp.example/settings/helpers?newNode=fs1.corp.example');assert.equal(starts,1);assert(!JSON.stringify(await page.evaluate(()=>({...sessionStorage}))).includes('PrivateSecret'));await page.reload();await link.waitFor();assert.equal(starts,1);await page.locator('.di-shell').screenshot({path:path.join(out,profile+'-complete.png')});assert.deepEqual(errors,[]);await page.close();
 }
 console.log('PASS member wizard: both identity profiles, member-only fields, password isolation, reload, enrollment link, mobile; screenshots:',out);
}finally{await browser.close();server.close();}})().catch(e=>{console.error(e);server.close();process.exitCode=1;});
